import {setupStorybook} from './storybook.mjs';
const $=s=>document.querySelector(s);
const newId=()=>crypto.randomUUID?.()||'memory-'+Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint8Array(8)),x=>x.toString(16).padStart(2,'0')).join('');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const prompts=[['Childhood','What did home look like when you were little?','⌂'],['People','Who taught you something you still carry with you?','❋'],['Beginnings','What do you remember about your first day in a new place?','↗'],['Traditions','Which family tradition would you like us to keep?','✧'],['Everyday life','What was an ordinary day like when you were seventeen?','☀'],['A message','What would you like the next generation to know?','♡']];
const sample={id:'example-blue-suitcase',example:true,title:'The blue suitcase',person:'An example storyteller',category:'Beginnings',language:'en',date:'2026-10-17T12:00:00Z',text:'When I was seventeen, I moved from my village to the city. My aunt met me at the bus station. We carried my blue suitcase to her apartment. I do not remember the year.',translation:'በአሥራ ሰባት ዓመቴ ከመንደሬ ወደ ከተማ ተዛወርኩ። አክስቴ አውቶቡስ ጣቢያ ተቀበለችኝ። ሰማያዊ ሻንጣዬን ወደ ቤቷ ተሸከምን። ዓመቱን አላስታውስም።'};
let questionIndex=0;
let stories=[],view='library',filter='all',search='',current=null,step=1,blob=null,audioUrl=null,recorder=null,stream=null,timer=null,audioContext=null,animation=null,elapsed=0,busy=false;
let config={url:location.port==='8000'&&['localhost','127.0.0.1'].includes(location.hostname)?location.origin:(window.SWK_CONFIG?.backendUrl||''),model:'llama3.2:3b'};
try{config={...config,...JSON.parse(localStorage.getItem('swk-config')||'{}')}}catch{}
let token=sessionStorage.getItem('swk-token')||'';
const dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('stories-we-keep',1);r.onupgradeneeded=()=>r.result.createObjectStore('stories',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function dbGet(){const db=await dbPromise;return new Promise((ok,no)=>{const r=db.transaction('stories').objectStore('stories').getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
async function dbPut(value){const db=await dbPromise;return new Promise((ok,no)=>{const tx=db.transaction('stories','readwrite');tx.objectStore('stories').put(value);tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
async function dbDelete(id){const db=await dbPromise;return new Promise((ok,no)=>{const tx=db.transaction('stories','readwrite');tx.objectStore('stories').delete(id);tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
const microphone=`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg>`;
function art(){const p=prompts[questionIndex];return `<div class="question-panel"><div class="question-top"><h2>A little help getting started</h2><span class="question-count">${questionIndex+1} of ${prompts.length}</span></div><h3>${esc(p[1])}</h3><p>Ask someone you love. Give them time to remember.</p><div class="question-actions"><button class="button secondary" id="useQuestion">Use this question</button><button class="text-button" id="nextQuestion">Try another</button></div></div>`}
function cards(){const items=[...stories,sample].filter(s=>(filter==='all'||s.language===filter)&&`${s.title} ${s.person} ${s.text}`.toLowerCase().includes(search.toLowerCase()));return items.map(s=>`<button class="story-card" data-story="${esc(s.id)}"><div class="card-title"><h3>${esc(s.title)}</h3><span>${esc(s.person||'Your family')}${s.example?' (fictional example)':''}</span></div><p class="card-excerpt" lang="${s.language}">${esc(s.text||'A memory waiting to be told.')}</p><div class="card-bottom"><span>${s.language==='am'?'አማርኛ':'English'}${s.translation?' / '+(s.language==='am'?'English':'አማርኛ'):''}</span><span>${s.audio?'Voice recording':'Written memory'}${s.duration?' ('+formatTime(s.duration)+')':''}</span></div></button>`).join('')+(items.length?'':'<p class="empty-filter">No stories match yet. Try another filter.</p>')+`<button class="add-card" id="addCard"><span aria-hidden="true">+</span> Add a family memory</button>`}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===view);b.setAttribute('aria-current',b.dataset.nav===view?'page':'false')});if(view==='prompts'){ $('#main').innerHTML=`<section class="prompts-heading"><h1>It starts with a question.</h1><p>Let them take their time. The smallest memories often hold the most.</p></section><div class="prompts-grid">${prompts.map((p,i)=>`<button class="prompt-card" data-prompt="${i}"><h2>${p[1]}</h2><span>${p[0]}</span></button>`).join('')}</div>`;document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>openNew(prompts[+b.dataset.prompt]));return}
$('#main').innerHTML=`<section class="hero"><div class="hero-copy"><h1>Record your family’s stories.</h1><p>Save the memories of your parents and grandparents in Amharic or English. Keep their voice, turn it into text, and pass the story on.</p><div class="hero-actions"><button class="button primary" id="newStory">${microphone} Record a story</button><button class="text-button" id="exploreExample">Read an example</button></div><p class="privacy-note">Their real voice. Their own words. Yours to keep.</p></div>${art()}</section><section class="archive" aria-label="Your storybook"><div class="section-top"><h2>Your family storybook <span class="story-number">(${stories.length})</span></h2><input class="search" id="search" type="search" aria-label="Search stories" placeholder="Find a memory…" value="${esc(search)}"></div><p class="storybook-note">Saved in this browser. Download a keepsake to back up or share a story.</p><div class="filters" aria-label="Filter by original language">${[['all','All stories'],['am','አማርኛ'],['en','English']].map(([v,t])=>`<button class="chip ${filter===v?'active':''}" data-filter="${v}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div><div class="story-grid" id="storyGrid">${cards()}</div></section><aside class="prompt-strip"><p>“What did home look like when you were little?”</p><button class="text-button" id="seePrompts">More questions to ask</button></aside>`;
$('#useQuestion').onclick=()=>openNew(prompts[questionIndex]);$('#nextQuestion').onclick=()=>{questionIndex=(questionIndex+1)%prompts.length;render();$('#nextQuestion').focus()};$('#newStory').onclick=()=>openNew();$('#exploreExample').onclick=()=>openStory(sample.id);$('#seePrompts').onclick=()=>{view='prompts';render();window.scrollTo(0,0)};$('#search').oninput=e=>{search=e.target.value;$('#storyGrid').innerHTML=cards();bindCards()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});bindCards()}
function bindCards(){document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>openStory(b.dataset.story));$('#addCard').onclick=()=>openNew()}
function formatTime(s){s=Math.round(s||0);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function setAudio(b){if(audioUrl)URL.revokeObjectURL(audioUrl);blob=b;audioUrl=b?URL.createObjectURL(b):null}
function openNew(p){current={id:newId(),title:'',person:'',category:p?.[0]||'Childhood',language:'am',text:'',translation:'',date:new Date().toISOString(),prompt:p?.[1]||''};step=1;setAudio(null);elapsed=0;renderEditor();$('#storyDialog').showModal()}
async function openStory(id){const s=id===sample.id?sample:stories.find(s=>s.id===id);if(!s)return;current={...s};setAudio(s.audio||null);step=2;renderEditor();$('#storyDialog').showModal()}
function captureFields(){if(!current)return;for(const [field,id] of [['title','storyTitle'],['person','storyPerson'],['language','storyLanguage'],['category','storyCategory'],['text','transcript'],['translation','translation']])if($('#'+id))current[field]=$('#'+id).value;}
function audioMarkup(){return audioUrl?`<audio class="audio-review" controls src="${audioUrl}" aria-label="Original story recording"></audio>`:'<p class="no-audio">Written memory. No audio attached.</p>'}
function renderEditor(){const original=current.language==='am'?'Amharic / አማርኛ':'English',target=current.language==='am'?'English':'Amharic / አማርኛ';$('#editor').innerHTML=`<div class="stepper"><span class="${step===1?'active':''}">1. Record</span><span class="${step===2?'active':''}">2. Review & keep</span></div><div class="editor-heading"><h2>${step===1?'Record a family story.':esc(current.title||'Keep their words close.')}</h2><p>${step===1?esc(current.prompt||'Find a quiet moment. Speak naturally, in the language that feels like home.'):(current.example?'See how the original story and its translation stay together.':'Review the words, then save this memory.')}</p></div>${current.example?'<div class="draft-note">Written example with an illustrative Amharic translation. Record your own story to keep the real voice alongside its words.</div>':''}
${step===1?`<div class="record-layout"><div class="record-panel"><h3>Record a memory</h3><button id="recordButton" class="record-button" aria-label="Start recording"></button><span class="timer" id="timer">${formatTime(elapsed)}</span><p id="recordHint">Tap to start. Up to 5 minutes at a time.</p><canvas class="record-wave" id="wave" width="500" height="60" aria-hidden="true"></canvas></div><div class="record-panel"><h3>Upload a recording</h3><p>Bring a voice note or a recording you already treasure.</p><label for="audioFile">Choose an audio file</label><input type="file" id="audioFile" accept="audio/*,.m4a,.mp3,.wav,.ogg,.webm,.flac"><p class="small">Up to 30 MB / 5 minutes</p></div></div><div id="audioHolder">${blob?audioMarkup():''}</div>`:`${audioMarkup()}`}
<div class="editor-fields"><label>A name for this memory<input id="storyTitle" maxlength="120" placeholder="e.g. The house with the blue door" value="${esc(current.title)}"></label><label>Whose story is this?<input id="storyPerson" maxlength="80" placeholder="e.g. Grandmother Almaz" value="${esc(current.person)}"></label><label>Original language<select id="storyLanguage" ${step===2?'disabled':''}><option value="am" ${current.language==='am'?'selected':''}>አማርኛ / Amharic</option><option value="en" ${current.language==='en'?'selected':''}>English</option></select></label><label>A chapter of life<select id="storyCategory">${prompts.map(p=>`<option ${p[0]===current.category?'selected':''}>${p[0]}</option>`).join('')}</select></label></div>
${step===2?`<div class="review-intro"><p>Review the original before translating. Keep names and dates as the storyteller intended.</p><button class="button secondary" id="translateButton">Translate to ${current.language==='am'?'English':'Amharic'}</button></div><div class="translation-grid"><label>${original} original<textarea id="transcript" lang="${current.language}" placeholder="Your transcript will appear here. You can also type or paste a story.">${esc(current.text)}</textarea></label><label>${target} translation<textarea id="translation" lang="${current.language==='am'?'en':'am'}" placeholder="Translate after reviewing the original, or add your own translation.">${esc(current.translation)}</textarea></label></div><p class="small">Translations are drafts. A family member should review meaning, names, and cultural expressions.</p>`:''}<div id="editorStatus" class="status" role="status"></div><div class="editor-bottom"><div class="button-row">${step===1?'<button class="text-button" id="writeInstead">Or write a memory</button>':'<button class="button primary" id="saveStory">Save memory</button><button class="button secondary" id="createStorybook">Create my storybook</button><button class="text-button" id="downloadStory">Download keepsake</button>'}</div><div class="button-row">${step===1?'<button class="button primary" id="transcribeButton">Transcribe recording</button>':`<button class="text-button" id="backRecord">${current.example?'Start your own story':'Change recording'}</button>${!current.example&&stories.some(s=>s.id===current.id)?'<button class="danger-link" id="deleteStory">Delete memory</button>':''}`}</div></div>`;
if(!config.url)status('AI transcription and translation are not connected yet. Recording and written memories are available.');if(step===1){$('#recordButton').onclick=toggleRecording;$('#audioFile').onchange=uploadAudio;$('#writeInstead').onclick=()=>{captureFields();step=2;renderEditor()};$('#transcribeButton').onclick=transcribe;}else{$('#createStorybook').onclick=()=>{captureFields();if(!openBook())status('Add your story before creating a storybook.',true)};$('#translateButton').onclick=translate;$('#saveStory').onclick=save;$('#downloadStory').onclick=download;$('#backRecord').onclick=()=>{if(current.example){$('#storyDialog').close();openNew()}else{captureFields();step=1;renderEditor()}};if($('#deleteStory'))$('#deleteStory').onclick=removeStory;}}
const openBook=setupStorybook({getStory:()=>current?{...current,audio:blob}:null,updateDraft:book=>{if(current)current.book=book},saveBook:async book=>{if(!current)return false;current.book=book;$('#storyTitle').value=book.title;$('#storyPerson').value=book.person;return await save()},notify:toast});
function setBusy(value){busy=value;document.querySelectorAll('#storyDialog button').forEach(b=>b.disabled=value)}
function status(message,error=false){const el=$('#editorStatus');if(el){el.textContent=message;el.className='status'+(error?' error':'')}}
async function toggleRecording(){if(recorder?.state==='recording'){stopRecording();return}if(!navigator.mediaDevices?.getUserMedia){status('Microphone recording is unavailable here. Please upload an audio file instead.',true);return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,type?{mimeType:type}:{});const chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{setAudio(new Blob(chunks,{type:recorder.mimeType}));if($('#audioHolder'))$('#audioHolder').innerHTML=audioMarkup();if(current)current.duration=elapsed;cleanupMedia();};recorder.start(1000);elapsed=0;$('#recordButton').classList.add('recording');$('#recordButton').setAttribute('aria-label','Stop recording');$('#recordHint').textContent='Recording… tap the square to finish.';$('#audioFile').disabled=true;$('#transcribeButton').disabled=true;$('#writeInstead').disabled=true;timer=setInterval(()=>{elapsed++;if($('#timer'))$('#timer').textContent=formatTime(elapsed);if(elapsed>=300)stopRecording()},1000);startWave();}catch(e){cleanupMedia();status('Microphone access was not available. Allow it in your browser, or upload a recording.',true)}}
function startWave(){try{audioContext=new AudioContext();const source=audioContext.createMediaStreamSource(stream),analyser=audioContext.createAnalyser();source.connect(analyser);analyser.fftSize=128;const data=new Uint8Array(analyser.frequencyBinCount);function draw(){const c=$('#wave');if(!c)return;const ctx=c.getContext('2d');analyser.getByteFrequencyData(data);ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--color-ink').trim();for(let i=0;i<50;i++){const h=Math.max(2,data[i]/5);ctx.fillRect(i*10,30-h/2,3,h)}animation=requestAnimationFrame(draw)}draw()}catch{}}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();clearInterval(timer);if($('#recordButton')){$('#recordButton').classList.remove('recording');$('#recordButton').setAttribute('aria-label','Start recording');$('#recordHint').textContent='Recording ready. Listen before continuing.';$('#audioFile').disabled=false;$('#transcribeButton').disabled=false;$('#writeInstead').disabled=false}}
function cleanupMedia(){clearInterval(timer);cancelAnimationFrame(animation);stream?.getTracks().forEach(t=>t.stop());stream=null;if(audioContext){audioContext.close().catch(()=>{});audioContext=null}}
async function uploadAudio(e){const f=e.target.files[0];if(!f)return;if(f.size>30*1024*1024){status('Please choose a recording smaller than 30 MB.',true);e.target.value='';return}setAudio(f);$('#audioHolder').innerHTML=audioMarkup();status('Recording ready. Choose its original language, then transcribe.');const a=new Audio(audioUrl);a.onloadedmetadata=()=>{if(Number.isFinite(a.duration))current.duration=a.duration}}
async function api(path,options={}){if(!config.url)throw new Error('AI transcription and translation are not connected yet. You can record, write a story, and download a keepsake.');const base=config.url.replace(/\/$/,'');let response;try{response=await fetch(base+path,{...options,headers:{...options.headers,...(token?{'X-API-Key':token}:{})},signal:AbortSignal.timeout(240000)})}catch(e){throw new Error(e.name==='TimeoutError'?'The request timed out. The first model download can take a few minutes. Try again after the backend finishes loading.':'Cannot reach the model backend. Open Connection and start your local backend, or enter its deployed address.')}let result;try{result=await response.json()}catch{throw new Error('The backend did not return a valid response. Check its address.')}if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'The request failed. Please check the backend.');return result}
async function transcribe(){if(!blob){status('Record or upload audio first, or choose “write a memory.”',true);return}captureFields();setBusy(true);status('Transcribing with the open speech model… First use may download the model.');try{const form=new FormData();form.append('audio',blob,'memory.'+(blob.type.includes('mp4')?'m4a':'webm'));form.append('language',current.language);const r=await api('/api/transcribe',{method:'POST',body:form});current.text=r.text;current.duration=r.duration;step=2;renderEditor();status('Transcript ready. Please listen and review the words before translating.')}catch(e){status(e.message,true)}finally{setBusy(false)}}
async function translate(){captureFields();if(!current.text.trim()){status('Add or transcribe the original story first.',true);return}setBusy(true);status('Translating with '+config.model+'…');try{const r=await api('/api/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:current.text,source:current.language,target:current.language==='am'?'en':'am',model:config.model})});current.translation=r.text;$('#translation').value=r.text;status('Translation ready for family review. The original is unchanged.')}catch(e){status(e.message,true)}finally{setBusy(false)}}
async function save(){captureFields();if(!current.text.trim()){status('Add a story before saving.',true);return}if(!current.title.trim()){status('Give this memory a title before saving.',true);$('#storyTitle').focus();return}const s={...current,id:current.example?newId():current.id,example:false,audio:blob,updated:new Date().toISOString()};try{await dbPut(s);stories=await dbGet();stories.sort((a,b)=>(b.updated||b.date).localeCompare(a.updated||a.date));$('#storyDialog').close();render();return true}catch{status('This browser could not save the story. Download a keepsake instead, and check available storage.',true)}}
async function removeStory(){if(!confirm('Delete this memory from this browser? Download a keepsake first if you want a backup.'))return;try{await dbDelete(current.id);stories=await dbGet();$('#storyDialog').close();render();toast('Memory deleted from this browser.')}catch{status('Could not delete this memory.',true)}}
function downloadFile(data,type,name){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function download(){captureFields();if(!current.text.trim()){status('Add a story before downloading.',true);return}const audio=blob?await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(blob)}):null;const title=esc(current.title||'A family memory');const html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}: Stories We Keep</title><style>:root{--paper:#fff7ee;--ink:#49333e;--muted:#735a64;--rule:#dbc4ba;--font:Arial,sans-serif;--unit:20px}html,body{overflow-x:clip}body{font:18px/1.8 var(--font);max-width:800px;margin:var(--unit) auto;padding:var(--unit);background:var(--paper);color:var(--ink)}h1{font-size:42px;line-height:1.15;overflow-wrap:break-word}h2{font-size:22px;border-top:1px solid var(--rule);padding-top:var(--unit);margin-top:var(--unit)}p{white-space:pre-wrap}audio{width:100%;margin:var(--unit) 0}small{font-size:14px;color:var(--muted)}footer{margin-top:var(--unit);border-top:1px solid var(--rule);padding-top:var(--unit)}@media print{audio{display:none}}</style><small>Stories We Keep / A family memory${current.example?' / Fictional example':''}</small><h1>${title}</h1><p>${esc(current.person)}</p>${audio?`<audio controls src="${audio}"></audio>`:''}<h2>${current.language==='am'?'አማርኛ':'English'} original</h2><p lang="${current.language}">${esc(current.text)}</p>${current.translation?`<h2>${current.language==='am'?'English':'አማርኛ'} translation</h2><p lang="${current.language==='am'?'en':'am'}">${esc(current.translation)}</p>`:''}<footer><small>Original words and recording preserved together. Translation is a draft unless reviewed by the family. Saved ${esc(new Date().toLocaleDateString())}. ${audio?'The recording is included in this file. ':''}This keepsake can be opened offline.</small></footer></html>`;downloadFile(html,'text/html;charset=utf-8',(current.title||'family-memory').replace(/[^\p{L}\p{N}-]+/gu,'-')+'.html');toast('Keepsake downloaded.')}
function openSettings(){ $('#backendUrl').value=config.url;$('#ollamaModel').value=config.model;$('#backendToken').value=token;$('#connectionResult').textContent='';$('#settingsDialog').showModal()}
$('#settingsOpen').onclick=openSettings;$('#aboutOpen').onclick=()=>$('#aboutDialog').showModal();document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render()});$('#settingsForm').onsubmit=e=>{e.preventDefault();config={url:$('#backendUrl').value.trim().replace(/\/$/,''),model:$('#ollamaModel').value.trim()};token=$('#backendToken').value.trim();localStorage.setItem('swk-config',JSON.stringify(config));sessionStorage.setItem('swk-token',token);$('#settingsDialog').close();toast('Connection saved. Your key stays in this browser tab session.')};$('#testConnection').onclick=async()=>{const el=$('#connectionResult');el.className='status';el.textContent='Checking speech backend and Ollama…';$('#testConnection').disabled=true;const previous={...config},previousToken=token;config.url=$('#backendUrl').value.trim();token=$('#backendToken').value.trim();try{const r=await api('/api/health');el.textContent=r.ollama?'Connected. Speech backend ready; Ollama models: '+(r.models.join(', ')||'none downloaded yet'):'Speech backend connected. Ollama is not available yet; transcription can still work.';$('#connectionDot').classList.add('connected');$('#modelOptions').innerHTML=(r.models||[]).map(m=>`<option value="${esc(m)}"></option>`).join('');}catch(e){el.className='status error';el.textContent=e.message;$('#connectionDot').classList.remove('connected')}finally{config=previous;token=previousToken;$('#testConnection').disabled=false}};
$('#storyDialog form').onsubmit=e=>{if(busy){e.preventDefault();toast('Please wait for the current model request to finish.')}};
$('#storyDialog').addEventListener('cancel',e=>{if(busy){e.preventDefault();status('Please wait for the current model request to finish.',true)}});$('#storyDialog').addEventListener('close',()=>{stopRecording();cleanupMedia();current=null;setAudio(null)});
try{stories=await dbGet();stories.sort((a,b)=>(b.updated||b.date).localeCompare(a.updated||a.date));}catch{toast('Browser storage is unavailable. You can still create and download a keepsake.')}render();
